 pub fn pending(&self)->bool{self.qualification.is_some()||self.registration.is_some()||self.admitting.is_some()||self.producer.is_some()||self.wire.is_some()||self.body.is_some()||self.command.is_some()||self.admission.is_some()||self.metadata.is_some()||self.caller.is_some()||self.receipt.is_some()||self.result.is_some()||!self.retirement.is_empty()}
