 pub fn close_demands(&self)->Result<RetirementDemand,ValueError>{let body=self.body.unwrap_or(0);if let Some(owner)=self.qualification.as_ref(){return if owner.terminal_is_empty(){let mut d=OriginalToolQualification::release_demands();d.copy_bytes=size_of::<Option<Box<OriginalToolQualification>>>();Ok(d)}else{owner.close_demands()}}if let Some(owner)=self.admitting.as_ref(){return if owner.terminal_is_empty(){let mut d=OriginalCommandAdmission::release_demands();d.copy_bytes=size_of::<Option<Box<OriginalCommandAdmission>>>();Ok(d)}else{owner.close_demands()}}if let Some(producer)=self.producer.as_ref(){return if producer.terminal_is_empty(){Ok(RetirementDemand{copy_bytes:size_of::<Option<Box<dyn semio_framework_plugin_decl_app::tool_contract::ArtifactOriginalCommandProducer<A::Command>>>>(),release_bytes:std::mem::size_of_val(&**producer),depth:1,..Default::default()})}else{producer.close_demands(body)}}if !self.retirement.is_empty(){return self.retirement.demands(body)}if self.result.is_some(){return self.retirement.next_owner_demands::<semio_framework::kernel::InvocationResult>(true,&None,body)}if self.metadata.is_some(){return self.retirement.next_owner_demands::<ActionMeta>(true,&None,body)}if self.command.is_some(){return self.retirement.next_owner_demands::<Box<A::Command>>(true,&None,body)}if self.admission.is_some(){return self.retirement.next_owner_demands::<AdmittedToolCommand>(true,&None,body)}if self.wire.is_some(){return self.retirement.next_owner_demands::<semio_framework::action_bus::RetainedToolWireInput>(true,&None,body)}if self.registration.is_some(){return self.retirement.next_owner_demands::<semio_framework_plugin_job::original_declared_tools::DeclaredToolRegistrationAlias>(true,&None,body)}if let Some(caller)=self.caller.as_ref(){return Ok(caller.retirement_demands())}if self.body.is_some(){return Ok(demand::<Self>())}Ok(Default::default())}
