 pub fn close_step(&mut self,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>{if !self.pending(){return Ok(true)}if !self.binding.is_some_and(|source|source.matches(cx))||self.decoder!=cx.native_receiving_identity(){return Err(refused().into())}if let Some(caller)=self.caller.as_ref(){caller.validate_retirement_context(cx)?;}if self.qualification.is_some(){self.close_qualification(cx)?;return Ok(false)}if self.admitting.is_some(){self.close_admitting(cx)?;return Ok(false)}if self.producer.is_some(){self.close_producer(cx)?;return Ok(false)}if self.registration.is_none()&&self.wire.is_none()&&self.command.is_none()&&self.admission.is_none()&&self.metadata.is_none()&&self.result.is_none()&&self.retirement.is_empty(){if let Some(caller)=self.caller.as_mut(){caller.close_step(cx.original_source_parent()?,cx)?;if caller.terminal_is_empty(){self.caller.take();}return Ok(false)}}let d=self.close_demands()?;close_original_retained_step(cx,d,|g|{if !self.retirement.is_empty(){return self.retirement.select(self.body.unwrap())?.step(g)}if self.result.is_some(){return Ok(self.retirement.begin_granted(&mut self.result,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}if self.metadata.is_some(){return Ok(self.retirement.begin_granted(&mut self.metadata,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}if self.command.is_some(){return Ok(self.retirement.begin_granted(&mut self.command,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}if self.admission.is_some(){return Ok(self.retirement.begin_granted(&mut self.admission,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}if self.wire.is_some(){return Ok(self.retirement.begin_granted(&mut self.wire,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}if self.registration.is_some(){return Ok(self.retirement.begin_granted(&mut self.registration,g)?.unwrap_or(RetainedCloneStep::Progress(Default::default())))}self.operation=None;self.receipt=None;self.action=None;self.argument=None;self.catalog=None;self.body=None;self.binding=None;self.decoder=None;Ok(RetainedCloneStep::Complete(progress(d)))})?;Ok(!self.pending())}
